    "identity": {
      "source": "ComfyUI_00002_.jpg",
      "instruction": "Maintain the exact facial structure, skin tone, and wavy dark hair. Ensure the transition between the direct gaze and the slightly angled, joyful expression in the second frame is fluid and gradual."
    },
    "attire": {
      "source": "ComfyUI_00002_.jpg",
      "instruction": "The red ruffled midi dress must remain perfectly consistent. The fabric is a high-quality matte cotton or linen. The ruffles at the neckline and the hem must maintain their density and volume as the skirt flares out during the turn."
    },
    "accessories": {
      "source": "ComfyUI_00002_.jpg",
      "instruction": "Gold rectangular drop earrings, gold bracelets on both wrists, and gold-strapped sandals must remain perfectly consistent in design and metallic sheen throughout the movement."
    }
  },
  "environment_setup": {
    "source": "ComfyUI_00002_.jpg",
    "location_type": "Premium studio fabric set",
    "backdrop_instruction": "Stable ivory/cream satin draped background. Implement a continuous wind-blown effect as if from a non-visible fan positioned on the left side of the frame, causing the satin to ripple and flow toward the right.",
    "lighting_instruction": "High-key, soft editorial studio lighting. Ensure the highlights on the red dress and the moving backdrop transition naturally without flickering."
  },
  "motion_safety_rules": {
    "body_orientation": "The transition involves a graceful partial clockwise turn. The model's weight shifts from both feet to a lead-foot step as seen in ComfyUI_00003_.jpg.",
    "arm_transition": "Hands must uncouple slowly from the center position. They move outward in a cinematic sweep to lightly grip and lift the sides of the skirt to create the flared effect.",
    "face_lock": "Strict identity lock. The facial features must not morph or drift during the rotation; eyes must track naturally with the head movement.",
    "garment_lock": "Physics-based fabric expansion. The skirt must transition from a flat hang to a wide flare without any texture 'crawling' or flickering, maintaining the ruffle integrity.",
    "motion_style": "Cinematic slow-motion. The twirl should feel effortless, airy, and high-end, with a seamless ramp-up and ramp-down in velocity."
  },
  "motion_plan": {
    "core_goal": "A seamless 6-second slow-motion transition from a still pose to a mid-action twirl with environmental wind.",
    "camera_motion": "Stationary digital cinema camera with a very slight, almost imperceptible slow-motion push-in (0.05x).",
    "subject_motion": "Model starts still. At 1.0s, she begins a slow, elegant half-turn. Her hands move to her sides to catch the dress. Her left foot steps forward as the skirt catches the air and flares out.",
    "fabric_motion": "Dual fabric interaction: The dress flares due to the twirl, while the background satin and the model's hair show a constant, graceful billow moving from left to right, driven by the off-screen fan.",
    "hair_motion": "Hair should swing with the turn and also flutter softly toward the right, reacting to the wind from the left."
  },
  "timeline_sequence": [
    {
      "time": "0.0s-1.0s",
      "action": "Hold start_frame. Model is centered, hands clasped. Background fabric begins to show the left-to-right wind rippling effect immediately."
    },
    {
      "time": "1.0s-5.0s",
      "action": "Slow-motion turn execution. Hands release and move outward. The red dress expands. The wind effect on the background intensifies slightly to match the dynamic movement of the twirl."
    },
    {
      "time": "5.0s-6.0s",
      "action": "Settle into end_frame. Maintain the wide flared pose. Background satin and dress hem continue to show a soft, wind-blown trailing motion toward the right."
    }
  ],
  "negative_prompt_shorthand": "extra fingers, identity drift, face morphing, flickering, jittering, hand position sliding, dress pattern crawling, lighting shifts, jerky neck movement, unnatural fabric stretching, fan visible in frame",
  "technical_overrides": {
    "consistency_weight": "maximum",
    "interpolation_smoothness": "maximum",
    "identity_lock_strength": "maximum",
    "motion_intensity": "medium-low"
  }
}

